[CmdletBinding()]
param(
    [switch]$ConfirmDevelopmentDatabase
)

$ErrorActionPreference = 'Stop'

# Development-only reconciliation. This script deliberately uses the owner
# account because it is database tooling, not an application write path.
if (-not $ConfirmDevelopmentDatabase) {
    throw 'Refusing to run without -ConfirmDevelopmentDatabase. This reconciler is development-only.'
}

Get-Content (Join-Path $PSScriptRoot '..\..\.env') | ForEach-Object {
    if ($_ -match '^([^#=]+)=(.*)$' -and -not [Environment]::GetEnvironmentVariable($matches[1].Trim())) {
        [Environment]::SetEnvironmentVariable($matches[1].Trim(), $matches[2].Trim(), 'Process')
    }
}

foreach ($name in 'DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_OWNER_USER', 'DB_OWNER_PASSWORD', 'DB_SSL_MODE', 'DB_TRUST_SERVER_CERTIFICATE') {
    if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name))) { throw "Missing required setting: $name" }
}

Add-Type -Path (Resolve-Path (Join-Path $PSScriptRoot '..\..\tools\migrator\bin\Debug\net8.0\Npgsql.dll'))
$builder = [Npgsql.NpgsqlConnectionStringBuilder]::new()
$builder.Host = $env:DB_HOST; $builder.Port = [int]$env:DB_PORT; $builder.Database = $env:DB_NAME
$builder.Username = $env:DB_OWNER_USER; $builder.Password = $env:DB_OWNER_PASSWORD
$builder.SslMode = [System.Enum]::Parse([Npgsql.SslMode], $env:DB_SSL_MODE, $true)
$builder.TrustServerCertificate = [bool]::Parse($env:DB_TRUST_SERVER_CERTIFICATE)

$seed = @(
    @{ employee_number='1'; first_name='Vladimir'; middle_name='Ljubiša'; last_name='Bogićević'; employment_start_date='2016-11-04'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='2'; first_name='Miloš'; middle_name='Sredoje'; last_name='Kodžopeljić'; employment_start_date='2016-11-04'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='3'; first_name='Marko'; middle_name='Radoš'; last_name='Rakonjac'; employment_start_date='2016-11-04'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='4'; first_name='Slobodan'; middle_name='Sredoje'; last_name='Kodžopeljić'; employment_start_date='2016-11-04'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='5'; first_name='Bojan'; middle_name='Dušan'; last_name='Petrović'; employment_start_date='2016-11-04'; employment_end_date='2021-12-16'; employment_status='Inactive' }, @{ employee_number='6'; first_name='Matije'; middle_name=$null; last_name='Vuković'; employment_start_date='2020-03-01'; employment_end_date='2023-12-31'; employment_status='Inactive' }, @{ employee_number='7'; first_name='Miloš'; middle_name=$null; last_name='Milić'; employment_start_date='2021-09-01'; employment_end_date='2023-12-31'; employment_status='Inactive' }, @{ employee_number='8'; first_name='Nikola'; middle_name=$null; last_name='Delić'; employment_start_date=$null; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='9'; first_name='Uroš'; middle_name=$null; last_name='Đoković'; employment_start_date='2023-01-01'; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='10'; first_name='Filip'; middle_name=$null; last_name='Nenadović'; employment_start_date=$null; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='11'; first_name='Petar'; middle_name=$null; last_name='Pajić'; employment_start_date='2023-01-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='12'; first_name='Okta'; middle_name=$null; last_name='Solutions'; employment_start_date='2016-11-04'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='13'; first_name='Nenad'; middle_name=$null; last_name='Miletić'; employment_start_date='2023-01-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='14'; first_name='Anđela'; middle_name=$null; last_name='Mandrapa'; employment_start_date=$null; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='15'; first_name='Anđelina'; middle_name=$null; last_name='Kodžopeljić'; employment_start_date='2023-01-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='16'; first_name='Jovana'; middle_name=$null; last_name='Tomašević'; employment_start_date=$null; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='17'; first_name='Stefan'; middle_name=$null; last_name='Rakonjac'; employment_start_date=$null; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='18'; first_name='Dragan'; middle_name=$null; last_name='Gojković'; employment_start_date=$null; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='19'; first_name='Filip'; middle_name=$null; last_name='Sretenović'; employment_start_date='2023-01-01'; employment_end_date='2023-12-31'; employment_status='Inactive' }, @{ employee_number='20'; first_name='Marija'; middle_name=$null; last_name='Vukomanović'; employment_start_date='2023-03-01'; employment_end_date='2023-11-15'; employment_status='Inactive' }, @{ employee_number='21'; first_name='Lazar'; middle_name=$null; last_name='Rajičić'; employment_start_date='2023-03-01'; employment_end_date='2023-12-31'; employment_status='Inactive' }, @{ employee_number='22'; first_name='Ivan'; middle_name=$null; last_name='Radovanović'; employment_start_date='2023-05-01'; employment_end_date='2026-01-31'; employment_status='Inactive' }, @{ employee_number='23'; first_name='Jelena'; middle_name=$null; last_name='Kodžopeljić'; employment_start_date='2024-01-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='24'; first_name='Jelena'; middle_name=$null; last_name='Miladinović'; employment_start_date='2024-01-01'; employment_end_date='2026-01-31'; employment_status='Inactive' }, @{ employee_number='1023'; first_name='Nebojša'; middle_name=$null; last_name='Gavrilović'; employment_start_date='2024-03-11'; employment_end_date=$null; employment_status='Inactive' }, @{ employee_number='2023'; first_name='Čedomila'; middle_name=$null; last_name='Milikić'; employment_start_date='2024-05-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='3023'; first_name='Miloš'; middle_name=$null; last_name='Jovanović'; employment_start_date='2023-12-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='3024'; first_name='Nikola'; middle_name=$null; last_name='Stiković'; employment_start_date='2023-12-01'; employment_end_date=$null; employment_status='Active' }, @{ employee_number='3025'; first_name='Vukašin'; middle_name=$null; last_name='Kuzmanović'; employment_start_date='2024-10-31'; employment_end_date='2024-12-31'; employment_status='Inactive' }, @{ employee_number='3026'; first_name='Mihailo'; middle_name=$null; last_name='Marković'; employment_start_date='2025-10-01'; employment_end_date=$null; employment_status='Active' }
)

# Only these original migration-004 seed rows may be removed.
$legacyNumbers = @('EMP-0001','EMP-0002','EMP-0003','EMP-0004','EMP-0005','EMP-0006','EMP-0007','EMP-0008','EMP-0009','EMP-0010')
$connection = [Npgsql.NpgsqlConnection]::new($builder.ConnectionString); $connection.Open(); $transaction = $connection.BeginTransaction()
try {
    $command = $connection.CreateCommand(); $command.Transaction = $transaction
    $command.CommandText = @'
CREATE TEMP TABLE employee_seed (employee_number varchar(30) PRIMARY KEY, first_name varchar(100), middle_name varchar(100), last_name varchar(100), employment_start_date date, employment_end_date date, employment_status varchar(30)) ON COMMIT DROP;
INSERT INTO employee_seed SELECT * FROM jsonb_to_recordset(@seed::jsonb) AS x(employee_number varchar(30), first_name varchar(100), middle_name varchar(100), last_name varchar(100), employment_start_date date, employment_end_date date, employment_status varchar(30));
CREATE TEMP TABLE reconciliation_result (kind text NOT NULL, employee_number varchar(30) NOT NULL, reason text NULL) ON COMMIT DROP;
INSERT INTO organization.departments (code,name,is_active) VALUES ('NERASPOREDJENI','Neraspoređeni',true) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name,is_active=true,updated_at=now() WHERE organization.departments.name IS DISTINCT FROM EXCLUDED.name OR organization.departments.is_active IS DISTINCT FROM true;
WITH department AS (SELECT id FROM organization.departments WHERE code='NERASPOREDJENI'), updated AS (UPDATE organization.employees e SET first_name=s.first_name,middle_name=s.middle_name,last_name=s.last_name,email=NULL,employment_start_date=s.employment_start_date,employment_end_date=s.employment_end_date,employment_status=s.employment_status,department_id=d.id,updated_at=now() FROM employee_seed s CROSS JOIN department d WHERE e.employee_number=s.employee_number AND (e.first_name,e.middle_name,e.last_name,e.email,e.employment_start_date,e.employment_end_date,e.employment_status,e.department_id) IS DISTINCT FROM (s.first_name,s.middle_name,s.last_name,NULL::varchar,s.employment_start_date,s.employment_end_date,s.employment_status,d.id) RETURNING e.employee_number), inserted AS (INSERT INTO organization.employees (employee_number,first_name,middle_name,last_name,email,employment_start_date,employment_end_date,employment_status,department_id) SELECT s.employee_number,s.first_name,s.middle_name,s.last_name,NULL,s.employment_start_date,s.employment_end_date,s.employment_status,d.id FROM employee_seed s CROSS JOIN department d LEFT JOIN organization.employees e ON e.employee_number=s.employee_number WHERE e.id IS NULL RETURNING employee_number) INSERT INTO reconciliation_result(kind,employee_number) SELECT 'updated',employee_number FROM updated UNION ALL SELECT 'inserted',employee_number FROM inserted;
INSERT INTO reconciliation_result(kind,employee_number) SELECT 'skipped',s.employee_number FROM employee_seed s WHERE NOT EXISTS (SELECT 1 FROM reconciliation_result r WHERE r.employee_number=s.employee_number);
WITH candidates AS (SELECT e.* FROM organization.employees e WHERE e.employee_number = ANY(@legacyNumbers) AND NOT EXISTS (SELECT 1 FROM employee_seed s WHERE s.employee_number=e.employee_number)), protected AS (SELECT c.employee_number,concat_ws('; ',CASE WHEN EXISTS (SELECT 1 FROM core.user_employee_links x WHERE x.employee_id=c.id) THEN 'identity user-to-employee link' END,CASE WHEN EXISTS (SELECT 1 FROM vacation.leave_requests x WHERE x.employee_id=c.id) THEN 'vacation leave request' END,CASE WHEN EXISTS (SELECT 1 FROM vacation.leave_balances x WHERE x.employee_id=c.id) THEN 'leave balance' END,CASE WHEN EXISTS (SELECT 1 FROM vacation.leave_policies x WHERE x.employee_id=c.id) THEN 'leave policy' END,CASE WHEN EXISTS (SELECT 1 FROM vacation.leave_balance_entries x WHERE x.employee_id=c.id) THEN 'append-only LV2 ledger entry' END,CASE WHEN EXISTS (SELECT 1 FROM audit.audit_events x WHERE x.target_public_id=c.public_id) THEN 'audit history' END) AS reason FROM candidates c), preserved AS (INSERT INTO reconciliation_result(kind,employee_number,reason) SELECT 'preserved',employee_number,reason FROM protected WHERE reason <> '' RETURNING employee_number), deleted AS (DELETE FROM organization.employees e USING candidates c LEFT JOIN protected p ON p.employee_number=c.employee_number WHERE e.id=c.id AND coalesce(p.reason,'')='' RETURNING e.employee_number) INSERT INTO reconciliation_result(kind,employee_number) SELECT 'removed',employee_number FROM deleted;
SELECT kind,employee_number,reason FROM reconciliation_result ORDER BY kind,employee_number;
'@
    [void]$command.Parameters.AddWithValue('seed', ($seed | ConvertTo-Json -Depth 3 -Compress))
    [void]$command.Parameters.AddWithValue('legacyNumbers', [NpgsqlTypes.NpgsqlDbType]::Array -bor [NpgsqlTypes.NpgsqlDbType]::Varchar, $legacyNumbers)
    $reader=$command.ExecuteReader(); $rows=@(); while($reader.Read()) { $rows += [pscustomobject]@{kind=$reader.GetString(0);employee_number=$reader.GetString(1);reason=if($reader.IsDBNull(2)){$null}else{$reader.GetString(2)}} }; $reader.Dispose(); $command.Dispose(); $transaction.Commit()
    $rows | Group-Object kind | ForEach-Object { [pscustomobject]@{ kind=$_.Name; count=$_.Count; employees=@($_.Group | ForEach-Object { if ($_.reason) { "$($_.employee_number): $($_.reason)" } else { $_.employee_number } }) } } | ConvertTo-Json -Depth 4
} catch { $transaction.Rollback(); throw } finally { $connection.Dispose() }
